'use strict';

const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
let pos = 0;

const N = data[pos++];
const M = data[pos++];
const K = data[pos++];

const spellA = data.slice(pos, pos + N);
pos += N;
const spellB = data.slice(pos, pos + N);
pos += N;

const mealA = data.slice(pos, pos + M);
pos += M;
const mealB = data.slice(pos, pos + M);
pos += M;

const Q = data[pos++];
const queries = data.slice(pos, pos + Q);

const MOD = 1000000007;
const SPLIT = 32768;

function mulMod(a, b) {
  const high = Math.floor(a / SPLIT);
  const low = a - high * SPLIT;
  return ((high * b % MOD) * SPLIT + low * b) % MOD;
}

function applyRepeated(a, b, count, value) {
  if (count === 0) return value;
  a %= MOD;
  b %= MOD;

  if (a === 1) {
    return (value + mulMod(b, count % MOD)) % MOD;
  }

  let resultA = 1;
  let resultB = 0;
  let baseA = a;
  let baseB = b;
  let n = count;

  while (n > 0) {
    if (n % 2 === 1) {
      resultB = (mulMod(baseA, resultB) + baseB) % MOD;
      resultA = mulMod(baseA, resultA);
    }

    baseB = (mulMod(baseA, baseB) + baseB) % MOD;
    baseA = mulMod(baseA, baseA);
    n = Math.floor(n / 2);
  }

  return (mulMod(resultA, value) + resultB) % MOD;
}

// Sort meals by descending b / (a - 1); a = 1 effects come first.
const meals = [];
for (let i = 0; i < M; i++) meals.push([mealA[i], mealB[i]]);

meals.sort((u, v) => {
  const [a1, b1] = u;
  const [a2, b2] = v;

  if (a1 === 1 && a2 !== 1) return -1;
  if (a1 !== 1 && a2 === 1) return 1;
  if (a1 === 1) return 0;

  const left = BigInt(b1) * BigInt(a2 - 1);
  const right = BigInt(b2) * BigInt(a1 - 1);
  if (left > right) return -1;
  if (left < right) return 1;
  return 0;
});

let mealMul = 1;
let mealAdd = 0;
for (const [a, b] of meals) {
  mealMul = mulMod(a % MOD, mealMul);
  mealAdd = (mulMod(a % MOD, mealAdd) + b) % MOD;
}

// Keep only the largest intercept for each spell multiplier.
const spellLines = [];
for (let i = 0; i < N; i++) spellLines.push([spellA[i], spellB[i]]);
spellLines.sort((u, v) => u[0] - v[0]);

const uniqueLines = [];
for (const line of spellLines) {
  const last = uniqueLines[uniqueLines.length - 1];
  if (last && last[0] === line[0]) {
    if (line[1] > last[1]) last[1] = line[1];
  } else {
    uniqueLines.push(line.slice());
  }
}

function ceilDiv(num, den) {
  const n = BigInt(num);
  const d = BigInt(den);
  if (n > 0n) return Number((n + d - 1n) / d);
  return Number(n / d);
}

// Upper hull for the spell lines, with integer starting points.
const hull = [];
for (const [a, b] of uniqueLines) {
  let start = -Infinity;

  while (hull.length > 0) {
    const last = hull[hull.length - 1];
    start = ceilDiv(last.b - b, a - last.a);
    if (start <= last.start) hull.pop();
    else break;
  }

  if (hull.length === 0) start = -Infinity;
  hull.push({ a, b, start });
}

const cap = hull.length > 1 ? Math.max(1, hull[hull.length - 1].start) : 1;

function findLine(x) {
  let lo = 0;
  let hi = hull.length;
  while (lo + 1 < hi) {
    const mid = (lo + hi) >> 1;
    if (hull[mid].start <= x) lo = mid;
    else hi = mid;
  }
  return lo;
}

const output = [];

for (const initialX of queries) {
  let x = Math.min(initialX, cap);
  let value = initialX % MOD;
  let remaining = K;

  while (remaining > 0) {
    const index = findLine(x);
    const line = hull[index];
    const a = line.a;
    const b = line.b;

    if (index === hull.length - 1) {
      value = applyRepeated(a, b, remaining, value);
      remaining = 0;
      break;
    }

    if (a === 1) {
      const nextStart = hull[index + 1].start;
      const stepsToNext = Number(
        (BigInt(nextStart - x) + BigInt(b) - 1n) / BigInt(b)
      );
      const count = Math.min(remaining, stepsToNext);

      value = applyRepeated(a, b, count, value);
      remaining -= count;

      const safeSteps = Number(BigInt(cap - x) / BigInt(b));
      if (count > safeSteps) x = cap;
      else x += count * b;
    } else {
      value = (mulMod(a % MOD, value) + b) % MOD;
      remaining--;

      const nextX = BigInt(a) * BigInt(x) + BigInt(b);
      x = nextX >= BigInt(cap) ? cap : Number(nextX);
    }
  }

  output.push(String((mulMod(mealMul, value) + mealAdd) % MOD));
}

console.log(output.join('\n'));
